
(function(){
  var page=document.getElementById('page'), wrap=document.getElementById('wrap');
  var cvL=document.getElementById('cvL'), cvU=document.getElementById('cvU');
  var brush=document.getElementById('brush'), sway=document.getElementById('sway');
  var pop=document.getElementById('pop'), popDone=document.getElementById('popDone');
  var anchor=document.getElementById('anchor'), words=document.getElementById('words');

  var imgNow=new Image(), imgWit=new Image();
  imgNow.src='data:image/png;base64,'; imgWit.src='data:image/png;base64,';

  var EYE1=[530,790,610,860], EYE2=[385,815,455,885];
  var done1=false, done2=false, finished=false, opened=false;
  var W=0,H=0,sx=1,sy=1,eraser=22;

  function dprScale(){ return Math.min(window.devicePixelRatio||1,2); }

  function sizeCanvas(){
    var r=wrap.getBoundingClientRect();
    var dpr=dprScale();
    W=r.width*dpr; H=r.height*dpr;
    cvL.width=W; cvL.height=H; cvU.width=W; cvU.height=H;
    var l=cvL.getContext('2d'), u=cvU.getContext('2d');
    l.drawImage(imgWit,0,0,W,H);
    u.drawImage(imgNow,0,0,W,H);
    sx=W/1152; sy=H/2048;
  }

  /* 毛笔: 初始在画布右上角(角落) */
  function placeBrush(){
    var r=wrap.getBoundingClientRect();
    var t=r.top+12, l=r.right-78;
    brush.style.transform='translate3d('+l+'px,'+t+'px,0) rotate(12deg)';
  }

  function localXY(e){
    var r=wrap.getBoundingClientRect();
    var s=dprScale();
    return [(e.clientX-r.left)*s, (e.clientY-r.top)*s];
  }

  function eraseAt(x,y,dot){
    var u=cvU.getContext('2d');
    u.globalCompositeOperation='destination-out';
    u.beginPath(); u.arc(x,y,eraser,0,Math.PI*2); u.fill();
    u.globalCompositeOperation='source-over';
    checkEyes();
  }

  function checkEyes(){
    if(finished) return;
    var u=cvU.getContext('2d');
    function ratio(rect){
      var x0=Math.round(rect[0]*sx), y0=Math.round(rect[1]*sy);
      var x1=Math.round(rect[2]*sx), y1=Math.round(rect[3]*sy);
      if(x1<=x0||y1<=y0) return 0;
      var d=u.getImageData(x0,y0,x1-x0,y1-y0).data;
      var tot=0,clear=0;
      for(var i=3;i<d.length;i+=4){ tot++; if(d[i]<210) clear++; }
      return clear/tot;
    }
    if(!done1 && ratio(EYE1)>0.35){ done1=true; glowAt(EYE1); }
    if(!done2 && ratio(EYE2)>0.35){ done2=true; glowAt(EYE2); }
    if(done1&&done2&&!finished) finish();
  }

  function glowAt(rect){
    var cx=((rect[0]+rect[2])/2)*sx/dprScale(), cy=((rect[1]+rect[3])/2)*sy/dprScale();
    var els=[];
    var g=document.createElement('div'); g.className='glow'; g.style.left=cx+'px'; g.style.top=cy+'px';
    var r=document.createElement('div'); r.className='eye-ring'; r.style.left=cx+'px'; r.style.top=cy+'px';
    var s=document.createElement('div'); s.className='eye-spark'; s.style.left=cx+'px'; s.style.top=cy+'px';
    els.push(g,r,s);
    for(var i=0;i<els.length;i++){ wrap.appendChild(els[i]); }
    requestAnimationFrame(function(){ g.classList.add('on'); r.classList.add('on'); s.classList.add('on'); });
    setTimeout(function(){ for(var j=0;j<els.length;j++){ if(els[j].parentNode) els[j].parentNode.removeChild(els[j]); } },1050);
  }

  function finish(){
    finished=true;
    brush.style.transition='opacity .5s'; brush.style.opacity='0';
    if(sway) sway.classList.remove('on');
    setTimeout(function(){ brush.style.display='none'; popDone.classList.add('on'); },450);
  }

  /* 弹窗打开: 初始化画布+毛笔 */
  function openPop(){
    opened=true;
    pop.classList.add('on');
    brush.style.opacity=''; brush.style.transition=''; brush.style.display='';
    done1=false; done2=false; finished=false;
    setTimeout(function(){
      if(W===0) sizeCanvas();
      placeBrush();
      brush.classList.add('show');
      requestAnimationFrame(function(){ brush.classList.add('idle'); });
      sway.classList.add('on');
    },120);
  }
  function closePop(){
    pop.classList.remove('on');
    page.classList.add('done');
    brush.classList.remove('show');
    brush.style.opacity=''; brush.style.transition=''; brush.style.display='';
  }

  anchor.addEventListener('click',function(e){ e.stopPropagation(); openPop(); });
  document.getElementById('closeBtn').addEventListener('click',function(){ closePop(); });

  /* 毛笔拖动 — 先 capture 再 preventDefault, 防 tap 路径下 pointerleave 抢事件 */
  brush.addEventListener('pointerdown',function(e){
    try{ brush.setPointerCapture(e.pointerId); }catch(err){}
    brush.classList.remove('idle');
    e.preventDefault();
    var p=localXY(e); eraseAt(p[0],p[1],true);
  });
  brush.addEventListener('pointermove',function(e){
    if(!e.buttons) return;
    var p=localXY(e);
    var cx=e.clientX-46, cy=e.clientY-92;
    brush.style.transform='translate3d('+cx+'px,'+cy+'px,0)';
    eraseAt(p[0],p[1],false);
  });
  brush.addEventListener('pointerleave',function(e){
    /* capture 已建立的情况下 leave 是假象, 吞掉 —— 否则 tap 路径下 brush 在 pointerdown
       后立刻收到 leave, 后续 move 不会到达 brush */
    if(brush.hasPointerCapture && brush.hasPointerCapture(e.pointerId)){ e.stopPropagation(); return; }
  });
  brush.addEventListener('pointerup',function(e){
    try{ if(brush.hasPointerCapture(e.pointerId)) brush.releasePointerCapture(e.pointerId); }catch(err){}
  });
  brush.addEventListener('pointercancel',function(){});
  brush.addEventListener('touchstart',function(e){e.preventDefault();}, {passive:false});

  var loadOK=0;
  imgNow.onload=imgWit.onload=function(){ if(++loadOK===2){ /* 弹窗打开时再 sizeCanvas */ } };
})();
